// A mathematical definition of the prefix‐count of true’s in a sequence.
// For any n with 0 ≤ n ≤ a.len(), prefix_count(a, n) counts the
// number of `true` values among a[0..n).
#[verifier::spec]
fn prefix_count(a: Seq<bool>, n: nat) -> nat {
    if n == 0 {
        0
    } else {
        prefix_count(a, n - 1)
        + (if a.index(n - 1) { 1 } else { 0 })
    }
}

